python3 - <<'PY'
import json, math
from pathlib import Path

def load(p):
    return json.loads(Path(p).read_text())

sub = load('/workspace/candidate/results.json')
rep = load('/workspace/audit/reproduced_results.json')
ev = load('/workspace/evidence/reproduced_results.json')
print('submitted==reproduced', sub==rep)
print('audit_reproduced==evidence_reproduced', rep==ev)
print('crit', sub.get('critical_speed'), rep.get('critical_speed'))

def walk(a,b,prefix=''):
    diffs=[]
    if type(a)!=type(b):
        return [(prefix,'type',type(a).__name__,type(b).__name__)]
    if isinstance(a, dict):
        keys=set(a)|set(b)
        for k in sorted(keys, key=str):
            if k not in a: diffs.append((prefix+'.'+str(k),'missing_in_a',None,b[k]))
            elif k not in b: diffs.append((prefix+'.'+str(k),'missing_in_b',a[k],None))
            else: diffs.extend(walk(a[k],b[k],prefix+'.'+str(k)))
    elif isinstance(a, list):
        if len(a)!=len(b):
            diffs.append((prefix,'len',len(a),len(b)))
        for i,(x,y) in enumerate(zip(a,b)):
            diffs.extend(walk(x,y,prefix+f'[{i}]'))
    elif isinstance(a, float) and isinstance(b, float):
        if not math.isclose(a,b,rel_tol=0,abs_tol=0):
            diffs.append((prefix,'float',a,b,abs(a-b)))
    else:
        if a!=b:
            diffs.append((prefix,'val',a,b))
    return diffs
diffs=walk(sub,rep)
print('n_diffs submitted vs reproduced', len(diffs))
for d in diffs[:30]:
    print(d)
PY
